import type { SVGProps } from "react";

/**
 * The app's icon set, as components.
 *
 * The SVGs live under `noun/` — see the README there for provenance and the
 * licence they are used under. They are wrapped rather than imported as files
 * so they behave like every other icon in the app: sized by class, coloured by
 * `currentColor` through the token layer, and hidden from assistive tech unless
 * a caller gives them a name.
 *
 * `aria-hidden` by default, because an icon beside a label is decoration. A
 * caller using one as the only content must supply its own accessible name.
 *
 * Attributes are the DOM spellings (`fillRule`, not `fill-rule`) — React warns
 * on the SVG ones and drops them, which silently changes how a path fills.
 *
 * Named exports only, so a page that draws one glyph bundles one glyph. The
 * full list lives in `gallery.ts`, which nothing but `/icons` imports — putting
 * it here would pull all of them into every chunk that touches this file.
 *
 * Generated from the purchased sets. Wire a glyph to a process in
 * `processIcons.tsx` rather than reaching for a raw SVG at a call site.
 */
export type IconProps = SVGProps<SVGSVGElement>;

